TLM.f("Commune/C10Pasc",{"officium":"Sancta Maria Sabbato Tempore Paschali: Salve Sancta parens","rule":["Gloria","Suffr=Spiritu;Ecclesiae,Papa;;","Prefatio=Maria=veneratione;"],"ruleInherited":["Gloria","Suffr=Spiritu;Ecclesiæ,Papa;;","Prefatio=Maria=veneratione;"],"fallback":"Commune/C10","sections":{"Introitus":[{"k":"rubric","la":"Sedulius"},{"k":"text","la":"Salve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum."},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Salve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum."}],"Oratio":[{"k":"text","la":"Concéde nos fámulos tuos, quǽsumus, Dómine Deus, perpétua mentis et córporis sanitáte gaudére: et, gloriósa beátæ Maríæ semper Vírginis intercessióne, a præsénti liberári tristítia, et ætérna pérfrui lætítia."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 24:14-16"},{"k":"text","la":"Ab inítio et ante sǽcula creáta sum, et usque ad futúrum sǽculum non désinam, et in habitatióne sancta coram ipso ministrávi. Et sic in Sion firmáta sum, et in civitáte sanctificáta simíliter requiévi, et in Jerúsalem potéstas mea. Et radicávi in pópulo honorificáto, et in parte Dei mei heréditas illíus, et in plenitúdine sanctórum deténtio mea."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis. Allelúja."},{"k":"ref","la":"Luc 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 19:25-27"},{"k":"text","la":"In illo témpore: Stabant juxta Crucem Jesu Mater ejus, et soror Matris ejus, María Cléophæ, et María Magdaléne. Cum vidísset ergo Jesus Matrem, et discípulum stantem, quem diligébat, dicit Matri suæ: Múlier, ecce fílius tuus. Deinde dicit discípulo: Ecce Mater tua. Et ex illa hora accépit eam discípulus in sua."}],"Offertorium":[{"k":"text","la":"Beáta es, Virgo María, quæ ómnium portásti Creatórem: genuísti qui te fecit, et in ætérnum pérmanes Virgo."}],"Secreta":[{"k":"text","la":"Tua, Dómine, propitiatióne, et beátæ Maríæ semper Vírginis intercessióne, ad perpétuam atque præséntem hæc oblátio nobis profíciat prosperitátem et pacem."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"text","la":"Beáta víscera Maríæ Vírginis, quæ portavérunt ætérni Patris Fílium."}],"Postcommunio":[{"k":"text","la":"Sumptis, Dómine, salútis nostræ subsídiis: da, quǽsumus, beátæ Maríæ semper Vírginis patrocíniis nos ubíque prótegi; in cujus veneratióne hæc tuæ obtúlimus majestáti."},{"k":"macro","name":"Per Dominum"}]},"hr":{"8742a4a90bf298f0":{"t":"Sedulije, Ps 44, 2\n(Sedulije) Zdravo, sveta Majko, koja si nam porodila Kralja koji vlada nebom i zemljom u vjekovječne vjekove! <i>Aleluja</i>, <i>aleluja</i>. (Ps 44, 2) Iz srca mi navire radosna riječ, pripovijedam svoja djela Kralju!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sedulije) Zdravo, sveta Majko, koja si nam porodila Kralja koji vlada nebom i zemljom u vjekovječne vjekove! <i>Aleluja</i>, <i>aleluja</i>.","v":"∅ → aleluia aleluia; ∅ → aleluia aleluia","kn":"Zdravo, sveta Majko, što nam porodi Kralja, koji vlada nebom i zemljom u vjekovječne vjekove! (Ps. 44, 2) Iz mog srca izvire divna pjesma: djela su moja namijenjena Kralju. Slava Ocu. Zdravo, <i>aleluja</i>, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 836–837 (snimka 419) (OCR)"},"82c77f3b838d2376":{"t":"<i>Pomolimo se</i>.\nDopusti nama, slugama svojim molimo, Gospodine Bože, da se neprestano radujemo duševnom i tjelesnom zdravlju i da se slavnim zagovorom blažene Marije vazda Djevice oslobodimo sadašnje žalosti i uživamo vječne radosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Dopusti nama, slugama svojim, molimo, Gospodine Bože, da se radujemo vječnome zdravlju duše i tijela i da se slavnim zagovorom blažene Marije, vazda Djevice, oslobodimo sadašnje žalosti i uživamo vječne radosti, po G. n.","knRef":"Kniewald 1942, str. 836–837 (snimka 419) (OCR)"},"7ead540ba882eb49":{"t":"Sir 24, 14-16\nČitanje knjige Mudrosti. Bila sam stvorena od početka i prije vjekova i neću prestati do vječnosti. Služila sam pred njim u svetom stanu. I tako sam se utvrdila na Sionu i u svetom sam gradu počinula i u Jeruzalemu je sjedište moje vlasti. Ukorijenila sam se u časnom narodu koji ima udio svoje baštine u mojemu Bogu, a moj je boravak u zboru svetih.","kn":"Čitanje Knjige mudrosti (Crkv. 24, 14-16). Bila sam stvorena od početka i prije vijekova, i ne ću prestati do vječnosti. Služila sam pred njim u svetomu stanu. I tako sam se utvrdila na Sionu i u svetomu sam gradu počinula i u Jeruzalemu je sjedište moje vlasti. Ukorijenila sam se u časnom narodu, koji imade dio svoje baštine u mojemu Bogu, a moj je boravak u zboru svetih.","knRef":"Kniewald 1942, str. 836–837 (snimka 419) (OCR)"},"2b14b2abf5e9a9e1":{"t":"Lk 1, 28\n<i>Aleluja</i>, <i>aleluja</i>.\nProcvala je mladica Jesejeva; Djevica je rodila Boga i čovjeka. Bog je vratio mir, u sebi pomirivši najniže s najvišim. <i>Aleluja</i>.\nZdravo Marijo, milosti puna. Gospodin s tobom, blagoslovljena ti među ženama. <i>Aleluja</i>.","kn":"Aleluja, aleluja (Br. 17, 18). Procvalo je Jesejevo žezlo; djevica je rodila Boga i čovjeka. Bog^ je vratio mir, u sebi pomirivši najniže s najvišim. Aleluja (Lk. 1, 28.) Zdravo Marijo, milosti puna. Gospodin s Tobom, blagoslovljena ti među ženama, aleluja.","knRef":"Kniewald 1942, str. 838–839 (snimka 420) (OCR)"},"0768acb23b8db282":{"t":"Iv 19, 25-27\nSlijedi sveto Evanđelje po Luki. U ono vrijeme: Stajale su kod križa Isusova njegova Majka i sestra Majke njegove Marija Kleofina i Marija Magdalena. Kada dakle vidje Isus Majku i učenika, koga ljubljaše gdje stoji, reče svojoj Majci: Ženo, evo ti sina. Zatim reče učeniku: Evo ti majke. I od onoga časa uze je učenik k sebi.","kn":"t Slijedi sveto Evanđelje po Ivanu (19, 25-27). U ono vrijeme stajale su uz Isusov križ njegova majka i sestra njegove majke Marija, Kleofina i Marija Magdalena. Kad je Isus viidio majku i uz nju učenika, kojega je ljubio, reče svojoj majci: Ženo, evo ti sina! Zatim reče učeniku: Evo ti majke! I od onoga časa uze je učenik k sebi.","knRef":"Kniewald 1942, str. 710–711 (snimka 356) (OCR)"},"bf13c33bec588b40":{"t":"Blažena si, Djevice Marijo, koja si nosila Stvoritelja svega; porodila si onoga koji te je stvorio i dovijeka ostaješ Djevica. <i>Aleluja</i>.","kn":"Blažena si, Djevice Marijo, koja si nosila Stvoritelja svega, rodila si onoga, koji je Tebe stvorioi 1 dovijeka ostaješ djevicom, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 678–679 (snimka 340) (OCR)"},"b5b1bdcbf7bad4ad":{"t":"Tvojim smilovanjem, Gospodine, i zagovorom blažene Marije, vazda Djevice, koristila nam ova žrtva za vječnu i sadašnju sreću i mir.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Tvojom milostivošću. Gospodine, i zagovorom blažene Marije, vazda Djevice, koristila nam ova žrtva za vječnu i' -sadašnju sreću i mir, po' G; n,","knRef":"Kniewald 1942, str. 838–839 (snimka 420) (OCR)"},"8587796109dd15d5":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože: i da te <i>u čašćenju</i> blažene Marije vazda Djevice hvalimo, blagoslivljamo i slavimo. Ona je osjenjena Duhom Svetim začela jedinorođenoga Sina tvoga i sačuvavši slavu djevičanstva prosula svijetom vječno svjetlo Isusa Krista Gospodina našega. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, da uvijek i, svagdje Tebi, Gospodine sveti. Oče svemogući, vječni Bože, zahvaljujemo i da Te hvalimo, slavimo i uzvisujemo o (Pohodu, Prikazanju, Bezgrješnom Začeću, Navještenju, Uznesenju. Rođenju, svetkovini) blažene Marije, vazda Djevice, koja je po Duhu Svetom začela jedinorođenoga Tvoga Sina i zadržavši slavu djevičanstva dala svijetu vječno svijetlo, Isuisa Krista, Gospodina našega, po kome anđeli hvale Tvoje veličanstvo, klanjaju Ti se gospodstva, podlažu Ti se vlasti, slave Te nebesa i nebeske sile s blaženim Serafinima kličući u zajedničkoj^ radosti. A mi Te molimo, da nam zapovjediš s njima sjediniti naše glasove smjerno ispovijedajući:","knRef":"Kniewald 1942, str. 22–23 (snimka 12) (OCR)"},"8410d46caf9ddbac":{"t":"Blaženo tijelo Marije Djevice koje je nosilo Sina vječnoga Oca, <i>aleluja</i>.","v":"∅ → aleluia","kn":"Blaženokrilo Djevice Marije, koje je nosilo Sina vječnoga Oca, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 838–839 (snimka 420) (OCR)"},"91ad6f2bf907ac82":{"t":"<i>Pomolimo se</i>.\nPrimivši, Gospodine, okrepe našega spasenja, molimo te, da nas svuda štiti zagovor blažene Marije vazda Djevice kojoj smo na čast prinijeli ove žrtve tvojemu veličanstvu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primivši, Gospodine, okrepe našega spasenja, molimo, da nas zakrili zaištita blažene Marije, vazda Djevice, kojoj smo na počast ovo prinijeli Tvojem veličanstvu, po G. n.","knRef":"Kniewald 1942, str. 704–705 (snimka 353) (OCR)"}}});
